sName={"custom-how-call-dot size-2 rounded-full bg-(--custom-primary)"} aria-hidden={"true"}></span>{"Charlotte Hale · "}<strong className={"font-semibold text-text"}>{"On a video call"}</strong></figcaption></figure></div><ol className={"timeline timeline--route timeline--numbered custom-how-track mt-[clamp(3rem,2rem_+_3vw,5rem)]"} data-anim={""}><li className={"timeline-item"}><div className={"timeline-item-marker"}><span className={"timeline-item-dot text-(--custom-ink)"}><i className={"ph-bold ph-chat-circle-text"} aria-hidden={"true"}></i></span><span className={"timeline-item-line"}></span></div><div className={"timeline-item-content"}><span className={"timeline-item-date"}>{"Day 1"}</span><h3 className={"timeline-item-title"}>{"Tell Us About You"}</h3><p className={"timeline-item-text max-w-72 mt-2 leading-[1.55]"}>{"Five minutes online or on the phone: what you earn, what you’ve saved, where you want to live."}</p></div></li><li className={"timeline-item"}><div className={"timeline-item-marker"}><span className={"timeline-item-dot text-(--custom-ink)"}><i className={"ph-bold ph-video-camera"} aria-hidden={"true"}></i></span><span className={"timeline-item-line"}></span></div><div className={"timeline-item-content"}><span className={"timeline-item-date"}>{"Day 2"}</span><h3 className={"timeline-item-title"}>{"Speak to an Adviser"}</h3><p className={"timeline-item-text max-w-72 mt-2 leading-[1.55]"}>{"We search 90+ lenders and talk you through the two or three deals that really fit."}</p></div></li><li className={"timeline-item"}><div className={"timeline-item-marker"}><span className={"timeline-item-dot text-(--custom-ink)"}><i className={"ph-bold ph-files"} aria-hidden={"true"}></i></span><span className={"timeline-item-line"}></span></div><div className={"timeline-item-content"}><span className={"timeline-item-date"}>{"Week 1"}</span><h3 className={"timeline-item-title"}>{"We Apply for You"}</h3><p className={"timeline-item-text max-w-72 mt-2 leading-[1.55]"}>{"We package the paperwork, submit it and keep chasing until the offer lands."}</p></div></li><li className={"timeline-item"}><div className={"timeline-item-marker"}><span className={"timeline-item-dot text-on-primary border-(--custom-primary) bg-(--custom-primary)"}><i className={"ph-bold ph-key"} aria-hidden={"true"}></i></span><span className={"timeline-item-line"}></span></div><div className={"timeline-item-content"}><span className={"timeline-item-date"}>{"Day 38"}</span><h3 className={"timeline-item-title"}>{"Keys in Hand"}</h3><p className={"timeline-item-text max-w-72 mt-2 leading-[1.55]"}>{"Exchange, completion and the bit everyone remembers — opening your own front door."}</p></div></li></ol></div></section><section id={"mg-calculators"} className={"custom-section"} aria-labelledby={"mg-calcs-title"}><div className={"container"}><div className={"custom-head custom-head--center"} data-anim={"fade-up"}><h2 id={"mg-calcs-title"} className={"custom-title"}>{"Run the numbers."}</h2><p className={"custom-lead"}>{"Three quick sums before you speak to anyone. Every figure here is illustrative."}</p></div><div className={"tabs tabs-underline tabs-justified tabs-feature custom-calcs-tabs max-w-256 mx-auto"} x-data={"{
                        tab: 'pay',
                        loan: 250000, rate: 4.25, years: 25,
                        price: 350000, ftb: false,
                        balance: 200000, oldRate: 7.24, newRate: 3.89,
                        gbp(n, d = 0) { return '£' + n.toLocaleString('en-GB', { minimumFractionDigits: d, maximumFractionDigits: d }) },
                        pay(p, a, y) { const r = a / 1200, n = y * 12; return r ? p * r / (1 - (1 + r) ** -n) : p / n },
                        sdlt(p, ftb) {
                            if (ftb && p <= 500000) return Math.max(0, p - 300000) * 0.05
                            const bands = [[125000, 0], [250000, 0.02], [925000, 0.05], [1500000, 0.1], [Infinity, 0.12]]
                            let tax = 0, from = 0
                            for (const [to, r] of bands) { if (p > from) tax += (Math.min(p, to) - from) * r; from = to }
