import Page10 from './pages/Page10.jsx';
const pages={"demo-mortgage-1":Page0,"demo-mortgage-1-about":Page1,"demo-mortgage-1-article":Page2,"demo-mortgage-1-calculators":Page3,"demo-mortgage-1-contact":Page4,"demo-mortgage-1-guides":Page5,"demo-mortgage-1-how-it-works":Page6,"demo-mortgage-1-mortgage":Page7,"demo-mortgage-1-mortgages":Page8,"demo-mortgage-1-rates":Page9,"demo-mortgage-1-reviews":Page10};
export default function App(){
const [page,setPage]=useState(()=>new URLSearchParams(location.hash.slice(1)).get('page')||"demo-mortgage-1");
useEffect(()=>{const change=()=>setPage(new URLSearchParams(location.hash.slice(1)).get('page')||"demo-mortgage-1");const navigate=e=>{const a=e.target.closest('a[href]');const href=a?.getAttribute('href');if(!href?.startsWith('#page='))return;const next=new URLSearchParams(href.slice(1)).get('page');if(!pages[next])return;e.preventDefault();e.stopPropagation();setPage(next);try{if(location.protocol!=='about:')history.pushState(null,'',href)}catch{}};document.addEventListener('click',navigate,true);window.addEventListener('hashchange',change);window.addEventListener('popstate',change);return()=>{document.removeEventListener('click',navigate,true);window.removeEventListener('hashchange',change);window.removeEventListener('popstate',change)}},[]);
useTemplateRuntime(page);const Page=pages[page]||Page0;return <div id='template-page' key={page}><Page/></div>;
}

